seq=''
for line in open('region.fasta'):
    if line.startswith('>'): continue
    seq+=line.strip().upper()
n=len(seq)
comp=str.maketrans('ACGT','TGCA')
rc=seq.translate(comp)[::-1]

def orfs(s, minaa=50):
    res=[]
    for strand,S in (1,seq),(-1,rc):
        for f in range(3):
            i=f
            while i < len(S)-2:
                if S[i:i+3]=='ATG':
                    j=i
                    while j < len(S)-2 and S[j:j+3] not in ('TAA','TAG','TGA'):
                        j+=3
                    aa=(j-i)//3
                    if aa>=minaa:
                        if strand==1: res.append((i+1, j+2, aa, strand))
                        else:
                            res.append((n-j, n-i+1, aa, strand))
                    i=j
                else:
                    i+=3
    return sorted(res)

for o in orfs(seq,30):
    print(o)
